Got it. Here's a **very simple** example of `realloc` in C:

```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    int *ptr = malloc(2 * sizeof(int)); // allocate space for 2 ints

    ptr[0] = 10;
    ptr[1] = 20;

    // Resize the memory to hold 3 ints
    ptr = realloc(ptr, 3 * sizeof(int));
    ptr[2] = 30;

    // Print all elements
    for (int i = 0; i < 3; i++) {
        printf("%d ", ptr[i]);
    }

    free(ptr); // free the memory
    return 0;
}
```

### Output:
```
10 20 30
```

